import{P as a}from"./chunks/PortfolioAnalysisChoice.ylVSFBjF.js";import{b as n,T as s}from"./chunks/theme.CMKb-o9K.js";import{o as l,c as d,j as t,a as i,G as o,a2 as r}from"./chunks/framework.BgSoyxN5.js";const g=JSON.parse('{"title":"Free Conservative Portfolio Builder","description":"Build a conservative virtual stock portfolio online using TickerForge quality, risk, diversification, and market-regime rules.","frontmatter":{"title":"Free Conservative Portfolio Builder","description":"Build a conservative virtual stock portfolio online using TickerForge quality, risk, diversification, and market-regime rules."},"headers":[],"relativePath":"portfolio-builder.md","filePath":"portfolio-builder.md","lastUpdated":1781852061000}'),c={name:"portfolio-builder.md"},v=Object.assign(c,{setup(u){return(h,e)=>(l(),d("div",null,[e[0]||(e[0]=t("h1",{id:"build-a-conservative-stock-portfolio",tabindex:"-1"},[i("Build a Conservative Stock Portfolio "),t("a",{class:"header-anchor",href:"#build-a-conservative-stock-portfolio","aria-label":'Permalink to "Build a Conservative Stock Portfolio"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Turn a blank virtual account into a structured watchlist of quality companies. The TickerForge portfolio builder screens the current stock universe, applies business-quality and risk limits, checks diversification, and adjusts exposure for the prevailing market regime. You see the proposed holdings before anything is created.",-1)),o(n,{"api-base":"https://api.ticker-forge.com"}),e[2]||(e[2]=t("h2",{id:"continue-from-construction-to-analysis",tabindex:"-1"},[i("Continue from Construction to Analysis "),t("a",{class:"header-anchor",href:"#continue-from-construction-to-analysis","aria-label":'Permalink to "Continue from Construction to Analysis"'},"​")],-1)),e[3]||(e[3]=t("p",null,"A proposed portfolio is only the starting point. Import your own holdings to run a private diagnostic draft, or inspect the live Conservative Quality model to see Portfolio Snapshot, Health Check, Sector Allocation, and Stress Test reports before building anything.",-1)),o(a),e[4]||(e[4]=r('<h2 id="conservative-is-the-demo-portfolio" tabindex="-1">Conservative Is the Demo Portfolio <a class="header-anchor" href="#conservative-is-the-demo-portfolio" aria-label="Permalink to &quot;Conservative Is the Demo Portfolio&quot;">​</a></h2><p>The web widget runs <strong>Conservative Quality</strong>, the portfolio type available to FREE users. It is the clearest way to test the portfolio engine: stable quality companies, steadier fundamentals, lower available volatility, diversification rules, and a market-aware cash buffer. It is still a virtual model, not a recommendation or a brokerage portfolio.</p><p>Inside Telegram, <code>Build Portfolio</code> can generate additional portfolios for different investment objectives:</p><table tabindex="0"><thead><tr><th>Portfolio</th><th>Focus</th><th>Access</th></tr></thead><tbody><tr><td><strong>Conservative Quality</strong></td><td>Stable quality companies with lower volatility</td><td>FREE</td></tr><tr><td><strong>Defensive</strong></td><td>Financial resilience and stronger downside protection</td><td>Standard</td></tr><tr><td><strong>Smart Money</strong></td><td>Quality stocks accumulated by tracked institutional funds</td><td>Standard</td></tr><tr><td><strong>Insider Accumulation</strong></td><td>Quality stocks with meaningful open-market insider buying</td><td>Standard</td></tr><tr><td><strong>AI Infrastructure</strong></td><td>Businesses positioned around AI capital spending</td><td>Standard</td></tr><tr><td><strong>Dividend Stocks</strong></td><td>Established dividend compounders in an accumulation zone</td><td>Standard</td></tr><tr><td><strong>Growth</strong></td><td>Quality businesses with stronger revenue and earnings growth</td><td>PRO</td></tr><tr><td><strong>Balanced</strong></td><td>A blend of defensive, growth, and dividend candidates</td><td>PRO</td></tr></tbody></table><p>Every type uses the same <code>buildPortfolioType</code> workflow, but supplies a different candidate universe and portfolio thesis.</p><h2 id="how-the-portfolio-builder-works" tabindex="-1">How the Portfolio Builder Works <a class="header-anchor" href="#how-the-portfolio-builder-works" aria-label="Permalink to &quot;How the Portfolio Builder Works&quot;">​</a></h2><p>Click <strong>Build Portfolio</strong> to request a Conservative Quality portfolio and view the result directly on this page. The engine evaluates the latest eligible companies rather than returning a fixed model portfolio. Candidates must pass fundamental quality, business risk, liquidity, and portfolio construction rules. The result is therefore allowed to change as company data and market conditions change.</p><p>TickerForge shows the proposed companies, diversification context, Portfolio Health scores, and current cash allocation. The portfolio can retain more cash when the market is defensive or panicked. Read about these checks in the <a href="/methodology/portfolio-health-check">Portfolio Health Score methodology</a> and the <a href="/methodology/market-stress-index">Market Stress Index</a>.</p><h2 id="what-you-receive-in-telegram" tabindex="-1">What You Receive in Telegram <a class="header-anchor" href="#what-you-receive-in-telegram" aria-label="Permalink to &quot;What You Receive in Telegram&quot;">​</a></h2><p>The first response is a portfolio blueprint, not a buy instruction. It shows the candidates that passed today, the proposed structure, and whether current conditions support investing the full virtual balance. If too few companies pass the rules, TickerForge can decline to build the portfolio instead of filling it with weaker names.</p><p>After reviewing the blueprint, you can create the portfolio inside Telegram and use it as an educational tracking account. The portfolio remains separate from your broker and uses virtual positions. TickerForge does not execute trades or move money.</p><h2 id="continue-your-research" tabindex="-1">Continue Your Research <a class="header-anchor" href="#continue-your-research" aria-label="Permalink to &quot;Continue Your Research&quot;">​</a></h2><p>Before accepting a company into any real portfolio, inspect its business quality, valuation, risk, institutional ownership, and timing. Enter one of the suggested tickers below to run the complete <strong>Check Stock</strong> workflow without leaving the page.</p>',13)),o(s,{"api-base":"https://api.ticker-forge.com","initial-query":"show Microsoft","initial-view":"business-data","utm-source":"portfolio-builder","utm-medium":"embedded_widget","utm-campaign":"web_stock_verdict","utm-content":"portfolio_builder_continue_research"}),e[5]||(e[5]=r('<p>You can also open the dedicated <a href="/stock-widget">Stock Verdict page</a>, explore the full <a href="/portfolio-analysis">portfolio analysis toolkit</a>, or compare portfolio access on the <a href="/pricing">pricing page</a>.</p><h2 id="related-read-next" tabindex="-1">Related / Read Next <a class="header-anchor" href="#related-read-next" aria-label="Permalink to &quot;Related / Read Next&quot;">​</a></h2><ul><li><a href="/import-portfolio">Import an existing portfolio</a> — analyze holdings you already own instead of building a new model.</li><li><a href="/portfolio-diagnostics">Try portfolio diagnostics demo</a> — inspect how public model portfolios behave under the same reports.</li><li><a href="/methodology/portfolio-health-check">Portfolio Health Check methodology</a> — understand the quality and concentration rules behind portfolio construction.</li><li><a href="/blog/illusion-of-diversification">The illusion of diversification</a> — learn why ticker count alone does not control portfolio risk.</li><li><a href="/blog/how-to-choose-assets-for-long-term-portfolio">How to choose assets for a long-term portfolio</a> — connect candidate selection with position roles and discipline.</li></ul><p>This builder is designed to make portfolio construction more concrete and repeatable. It is an educational decision-support tool, not personalized financial advice or a promise of investment performance.</p>',4))]))}});export{g as __pageData,v as default};
